window.weaponsPage=function(){main.innerHTML=header('Weapons & upgrades','A spoiler-light weapon path: what to look for in the Mines, where to buy replacements, and how upgrading actually works.')+`<div class="notice weapon-answer"><strong>Important:</strong> Clint does not upgrade weapons. In Year 1, “upgrading” usually means finding a stronger weapon in mine chests or buying one from the Adventurer’s Guild, just east of the Mines.</div><section class="weapon-place"><div><p class="eyebrow">Where to shop</p><h2>Adventurer’s Guild</h2><p>Open daily from 2:00pm–2:00am after completing the short Initiation quest. Marlon sells weapons, boots, and rings; his weapon stock grows as you reach deeper mine floors.</p></div><img src="assets/weapons/rusty-sword.png" alt="Rusty Sword" loading="lazy"></section><div class="reference-grid weapon-grid">${weaponData.map(w=>`<article class="reference-card weapon-card"><img src="assets/weapons/${w[1]}" alt="${w[0]}" loading="lazy"><div><p class="eyebrow">${w[2]}</p><h2>${w[0]}</h2><p>${w[3]}</p></div></article>`).join('')}</div><section class="section"><div class="section-title"><h2>Choose your weapon style</h2></div><div class="card-grid"><article class="card"><h3>Sword</h3><p>The easiest all-rounder. Its special move blocks and knocks enemies back.</p></article><article class="card"><h3>Dagger</h3><p>Very fast and close-range. Its special move delivers several quick stabs.</p></article><article class="card"><h3>Club</h3><p>Slower, heavy hits with strong knockback. Its special move slams nearby enemies.</p></article></div></section><details class="late-game-note"><summary>Later-game weapon upgrading — light location spoiler</summary><div class="notice"><strong>The Forge:</strong> much later, the Forge on floor 10 of the Volcano Dungeon can improve a melee weapon up to three times using a gem plus Cinder Shards. It can also add enchantments. You do not need this for your current mine progress.</div></details><p class="tiny source-note">Weapon pictures, damage, locations, and upgrade mechanics reference: Stardew Valley Wiki.</p>`};

const skillSections={
  Farming:[['Morning order','Check weather, pet and feed animals, collect produce, then water only the tiles not covered by sprinklers.'],['Crop math','Growth time starts after planting day. Count the listed days forward and leave room before day 28.'],['Machine rhythm','Keep raw products moving: eggs → mayonnaise, milk → cheese, wool → cloth, truffles → oil.'],['Spring preparation','Quality Sprinklers water 8 neighboring tiles and need an Iron Bar, Gold Bar, and Refined Quartz.']],
  Mining:[['Elevator checkpoints','The elevator records every five floors. Aim for the next multiple of five instead of pushing until collapse.'],['Ore regions','Copper is common on floors 1–39, iron on 40–79, and gold on 80+. Your floor determines the best material target.'],['Pack for the trip','Bring food, leave inventory space, and watch both health and time. Ladders matter more than clearing every rock.'],['Your current depth',()=>`Your notes say floor ${currentFarm().mine}. A gentle next checkpoint is ${Math.min(120,Math.ceil((+currentFarm().mine+1)/5)*5)}.`]],
  Fishing:[['The four variables','A catch depends on season, location, time, and weather. If one fish will not appear, check all four.'],['Training plan','Use the Training Rod at low Fishing levels, choose easier pond or mountain-lake fish, and practice in short sessions.'],['Treasure vs catch','Do not chase treasure if it makes you lose the fish. Secure the catch first.'],['Food buffs','Fishing food temporarily widens the bar. Dish O’ The Sea is a useful example once you can cook it.']]
};
window.fieldGuidePage=function(){main.innerHTML=header('Farming, mining & fishing','Three practical mini-guides for the skills you use most, kept beginner-friendly and spoiler-light.')+`<div class="skill-tabs">${Object.keys(skillSections).map((s,i)=>`<button class="${i===0?'active':''}" data-skill="${s}">${s}</button>`).join('')}</div><div id="skillPanel"></div>`;const draw=s=>{document.querySelector('#skillPanel').innerHTML=`<div class="card-grid skill-grid">${skillSections[s].map(x=>`<article class="card"><h3>${x[0]}</h3><p>${typeof x[1]==='function'?x[1]():x[1]}</p></article>`).join('')}</div>`};draw('Farming');document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-skill]').forEach(x=>x.classList.toggle('active',x===b));draw(b.dataset.skill)})};

route();
